"""The variable registry and the table-mapping ledger.

Two dictionaries, one rule:
  * data/variables.yaml    the registry: what a variable is called here, its unit and plausible limits.
  * data/table_mappings.json  the ledger (generated by app/nimbus/tables.py): for each PSI test table,
                            keyed by file name AND the table's SHA-256, which header maps to which key.
  * data/mappings/PSI-*.yaml  hand-reviewed mappings. They win over the ledger.

A mapping applies only to the exact table it was made for. If the table's SHA-256 in the snapshot
manifest no longer matches, the mapping is blocked ("stale") until the table is mapped again, and the
dashboard says a data refresh is needed. Every table gets an explicit status: nothing is skipped silently.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

import yaml

STATUSES = ("mapped", "stale", "not mappable", "no mapping yet", "superseded")
REASONS = {
    "superseded": "Another table, built from the lab's own workbook, contains every test in this one, so this one is not counted again.",
    "evidence_missing": "A quote that backs this hand-reviewed mapping is no longer found in the PSI document; data refresh needed.",
    "table_changed": "The table changed after it was mapped; data refresh needed.",
    "not_mapped_yet": "No mapping has been made for this table yet.",
    "no_test_id": "The table has no column that numbers each test.",
    "test_id_not_unique": "The test-number column repeats values, so rows can't be told apart.",
    "ambiguous_columns": "Two or more headers could hold the same quantity (for example before and after a test) and none was chosen.",
    "no_condition_columns": "The table has no oxygen or pressure column (it lists samples or notes, not test conditions).",
    "unknown_outcome_values": "The outcome column has values the registry does not define, so it is not mapped until they are reviewed.",
    "no_unit_in_header": "The oxygen or pressure header doesn't state a unit, so none is assumed.",
    "multi_value_cells": "Cells hold several values (a test plan such as '0.17; 0.21; 0.25'), so there is no single value per test.",
    "sparse_or_non_numeric": "Most cells in the oxygen or pressure column are blank, approximate or not numbers.",
    "oxygen_role_unknown": "Nothing in the table says its oxygen describes the surrounding air.",
    "not_mappable": "No column passed the checks.",
}


def load_registry(path: Path) -> dict:
    """The variable registry, with each header and unit pattern compiled."""
    raw = yaml.safe_load(path.read_text(encoding="utf-8"))
    doc = {**raw["variables"], **raw.get("outcomes", {})}        # one dictionary: measured variables and outcome columns
    for key, spec in doc.items():
        bad = [k for k in spec.get("values", {}) if not isinstance(k, str)]
        if bad:                                                   # YAML reads bare yes/no as booleans
            raise ValueError(f"{key}: category values {bad} must be quoted text")
        spec["header_re"] = [re.compile(p, re.I) for p in spec.get("header", [])]
        spec["unit_re"] = {u: [re.compile(p, re.I) for p in pats] for u, pats in spec.get("units", {}).items()}
        spec["key"] = key
    return doc


def registry_hash(path: Path) -> str:
    import hashlib
    return hashlib.sha256(path.read_bytes()).hexdigest()[:16]


def _flat(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip().lower()


def verify_evidence(snapshot: Path, evidence: list[dict]) -> list[str]:
    """Problems with a hand mapping's evidence. Each item names a PSI document, a page and a quote; the quote must be
    in that document word for word (spacing and capitals aside) and on that page. An empty list means every quote checks out."""
    problems = []
    for item in evidence or []:
        path = snapshot / "docs" / item["file"]
        if not path.exists():
            problems.append(f"{item['file']}: document is not in the snapshot")
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        pages = re.split(r"\[\[(?:page|sheet) ([^\]]+)\]\]", text)
        # re.split with one group: [before, label1, text1, label2, text2, ...]
        body = {str(pages[i]).strip(): _flat(pages[i + 1]) for i in range(1, len(pages) - 1, 2)}
        page = str(item.get("page", "")).strip()
        haystack = body.get(page) if page else _flat(text)
        if haystack is None:
            problems.append(f"{item['file']}: no page {page!r}")
        elif _flat(item["quote"]) not in haystack:
            problems.append(f"{item['file']} page {page}: quote not found: {item['quote'][:60]!r}")
    return problems


def load_ledger(path: Path) -> dict[str, dict]:
    """{table file name: ledger entry}. Empty when no ledger has been generated."""
    if not path.exists():
        return {}
    return json.loads(path.read_text(encoding="utf-8")).get("tables", {})


def resolve(name: str, sha256: str, hand: dict[str, dict], ledger: dict[str, dict]) -> dict:
    """Decide what a table gets. Returns {"mapping": dict|None, "status", "reason_code", "reason", "source"}."""
    def out(mapping, status, code=None, source=None):
        return {"mapping": mapping, "status": status, "reason_code": code, "source": source,
                "reason": REASONS.get(code) if code else None}

    h = hand.get(name)
    if h is not None:
        pinned = h.get("sha256")
        if pinned and pinned != sha256:
            return out(None, "stale", "table_changed", "hand-reviewed")
        return out(h, "mapped", None, "hand-reviewed")
    entry = ledger.get(name)
    if entry is None:
        return out(None, "no mapping yet", "not_mapped_yet")
    if entry["sha256"] != sha256:
        return out(None, "stale", "table_changed", "ledger")
    if entry["status"] == "mapped":
        return out({**entry["mapping"], "investigation": entry["investigation"]}, "mapped", None, entry.get("provenance", "rules"))
    return out(None, "not mappable", entry.get("reason_code") or "not_mappable", "ledger")
